import{b as e,O as t,g as p,j as l}from"./chunks/framework.DcaUmd3X.js";const d=JSON.parse('{"title":"人性的弱点","description":"","frontmatter":{},"headers":[],"relativePath":"reading/digital/how-to-win-friends/index.md","filePath":"读书感悟/电子书架/36.人性的弱点.md","lastUpdated":1781614933000}'),c={name:"reading/digital/how-to-win-friends/index.md"};function u(b,o,q,k,a,r){return t(),p("div",null,[...o[0]||(o[0]=[l('<h1 id="人性的弱点" tabindex="-1">人性的弱点 <a class="header-anchor" href="#人性的弱点" aria-label="Permalink to &quot;人性的弱点&quot;">​</a></h1><p><code>卡耐基</code> <code>励志成长</code></p><h2 id="书摘" tabindex="-1">书摘 <a class="header-anchor" href="#书摘" aria-label="Permalink to &quot;书摘&quot;">​</a></h2><blockquote><p>📌 一个人的成功，只有15%归结于他的专业知识，另外的85%要归结于他的表达思想、领导他人及唤起他人热情的能力。</p></blockquote><blockquote><p>📌 我们要知道，批评就好比家养的鸽子，它们到时候总是要回家寻找主人的</p></blockquote><blockquote><p>📌 只有你不议论别人，别人才不会议论你”</p></blockquote><blockquote><p>📌 请记住待人处世的技巧：不要批评、指责或抱怨别人。</p></blockquote><blockquote><p>📌 我认为我所拥有的最大资本，就是我鼓动、激发职工的热情的能力。而充分发挥一个人才能的方法，正是赞赏和鼓励。”</p></blockquote><blockquote><p>📌 “在这个世界上，上司的批评最容易扼杀一个人的雄心壮志。我从来都不批评任何人。我认为应给人以工作方面的激励。所以我更加乐于称赞，而不喜欢挑剔。如果说我有什么偏好的话，那就是我‘诚于嘉许，宽于称道’”。</p></blockquote><blockquote><p>📌 “不要害怕那些攻击你的敌人，但要小心那些恭维你的朋友。”</p></blockquote><blockquote><p>📌 凡是我所遇见的人，都在某些方面比我强。在这些方面，我应该向他们学习。”</p></blockquote><blockquote><p>📌 世界上能够影响他人的唯一方法，就是谈论他人的需要，并告诉他应该如何去获得它。</p></blockquote><blockquote><p>📌 如果成功有什么秘诀的话，那就是站在对方的立场来看待问题，如同用你自己的观点看事情一样，并要具备审时度势的能力。”</p></blockquote><blockquote><p>📌 小册子《乐于施舍者》和《分享财富》送给他。如果他读了这两本书，并在实际生活中加以应用的话，他将会赚到更多的钱——比代办我的保险要多上千倍。 亚拉巴马州伯明翰市的卢卡斯介绍了同一个公司两名推销员在处理同</p></blockquote><blockquote><p>📌 能够设身处地为别人着想、洞察别人心理的人，永远不必担心自己的前途。”</p></blockquote><blockquote><p>📌 永远从别人的立场去思考，并从他的角度来看问题”，那么你这一生就会有一个新的里程碑。</p></blockquote><blockquote><p>📌 自我表现是人类天性中最为重要的因素。”</p></blockquote><blockquote><p>📌 无论发生什么事，永远都要保持自我本色。</p></blockquote><blockquote><p>📌 “人不会因为工作过于疲劳而死亡，却会死于浪费和忧虑。”</p></blockquote><blockquote><p>📌 要想轻松自在，先得由放松自己的两眼和脸部开始，口里不断重复：“放松……放松……松弛下来……”你可以感到一种活力从脸上肌肉中逸出，进入身体内部。这时你会觉得自己远离压力，像婴孩般自由自在。</p></blockquote><blockquote><p>📌 精神崩溃，因无法入眠、忧虑、胃溃疡而大受折磨的猫。 第二，尽量在舒适的情况下工作。记住，身体的紧张会导致肩痛和精神疲劳。 第三，每天自省四五次，并且自问：“我做事有没有讲求效率？有没有让肌肉做不必要的</p></blockquote><blockquote><p>📌 别的地方也不可能找到快乐。 你要不停地提醒自己，要对自己的工作感兴趣，这样就能使你不再忧虑，而且最后还有可能给你带来升迁和加薪的机会。即使事情没有这么好的结果，那至少也可以使你的疲劳降到最低程度，使你</p></blockquote><blockquote><p>📌 家，他只用了一句话作为一生的总结——这也是决定人类命运的一句话：“思想决定一生。” 如果思想是快乐的，那我们就是快乐的；如果脑子里想的东西都是凄惨的，我们就会变得凄惨。有恐惧的想法，就会产生心理恐惧。</p></blockquote><blockquote><p>📌 思想决定一生。”</p></blockquote><blockquote><p>📌 祛除不当的心思，比割除身上的毒瘤更重要。</p></blockquote><blockquote><p>📌 伟大的法国哲学家蒙田把下面这句话奉为一生的圭臬：“伤害人的并非事件本身，而是他对事件的看法。”</p></blockquote><blockquote><p>📌 如果我们拥有平静的思想，就能坐在自己的棺木上欣赏风景，在饥寒交迫时犹能欢唱。</p></blockquote><blockquote><p>📌 行动似乎跟着感觉走，其实行动与感觉是并行的，多以意志控制行动，也就能间接控制感觉。</p></blockquote><blockquote><p>📌 如果只要想得开心积极，就能救回一个人的生命，我们何必还要为一点芝麻小事去烦躁呢？如果只要过得开心就能创造快乐，又何必让自己及周围的人难过呢？</p></blockquote><blockquote><p>📌 一个人的想法决定他是个什么样的人。</p></blockquote><blockquote><p>📌 除了你自己，没有别人能带给你平安。</p></blockquote><blockquote><p>📌 只要将一个人内心的态度由恐惧转为奋斗，便能够克服任何障碍。</p></blockquote><blockquote><p>📌 本华曾说：“庸俗的人在伟人的错误和愚行中，得到自己最大的快感。”</p></blockquote><blockquote><p>📌 不公正的批评通常是一种伪装过的恭维。因为从来没有人愿意踢一只死了的狗。</p></blockquote><blockquote><p>📌 我父亲从不浪费一分钟去想那些他不喜欢的人。</p></blockquote><blockquote><p>📌 能生气的人是傻瓜，不会生气的人才是智者。</p></blockquote><blockquote><p>📌 要想真正宽恕并忘却我们的敌人，最有效的办法就是诉诸比我们强大的力量。</p></blockquote><blockquote><p>📌 永远不要对敌人心存报复，否则，对自己的伤害将大过对别人的。</p></blockquote><blockquote><p>📌 但我们这个世界上唯一能够得到爱的办法，就是不再去乞求，而是立即开始付出，并且不希望得到回报。</p></blockquote><blockquote><p>📌 我正在因为自己没有鞋而难过，忽然遇见一个没有双脚的人，我的难过顿时消失了。</p></blockquote><blockquote><p>📌 我们的生活中大概有90%的事，都进行得很顺利，而只有10%出现问题。</p></blockquote><blockquote><p>📌 所表现出来的永远只是内心世界的反映</p></blockquote><blockquote><p>📌 罗根·史密斯有一句智慧之言：“人生有两项主要目标，第一，拥有你所向往的；第二，享受它们。只有最具智慧的人才能做到第二点。”</p></blockquote><blockquote><p>📌 两个人由铁窗往外望， 一人看到满地的泥泞， 另一人，却看到满天星辰。</p></blockquote><blockquote><p>📌 美好的事往往也是最困难的事。</p></blockquote><blockquote><p>📌 人生最重要的不是以你的所得作投资，因为任何人都可以这样做。真正重要的是如何从损失中获利。这才需要智慧，也才能显示出人的素质高低。</p></blockquote><blockquote><p>📌 这就是人生，断了一条弦，就用剩余的弦继续演奏</p></blockquote><blockquote><p>📌 人生最重要的不只是运用自己所拥有的，因为任何人都会这样做，真正重大的课题是如何从你的损失中获益，这需要真正的智慧，也只有这样才显示出你的雄才大略。</p></blockquote><blockquote><p>📌 把玫瑰送给别人，你的手上总能沾点余香。</p></blockquote><blockquote><p>📌 我该了解到，没有人真正关心别人的事，他们关切自己轻微的头痛，可能比关切你我的死讯还要多。</p></blockquote><blockquote><p>📌 如果你身居领导地位，那就注定要被批评，想办法习惯它吧！</p></blockquote><blockquote><p>📌 一般人常因他人的批评而愤怒，有智慧的人却想办法从中学习。</p></blockquote><blockquote><p>📌 记下自己干过的蠢事，提出自我批评。</p></blockquote><blockquote><p>📌 对别人漠不关心的人，他一生的困难最多，对别人的损害也最大。所有人类的失败，都是由这些人所造成的。</p></blockquote><blockquote><p>📌 要让别人喜欢你的第一原则： 要真诚地关怀他人！</p></blockquote><blockquote><p>📌 大多数人的快乐，与他们内心当中所想要得到的快乐，相差无几。</p></blockquote><blockquote><p>📌 喜欢挑剔的人，甚至是最激烈的批评者，也常常会在一个具有忍耐心和同情心的倾听者面前软化。</p></blockquote><blockquote><p>📌 人类的行为有个极为重要的法则，这个法则就是：时时让别人感到重要。</p></blockquote><blockquote><p>📌 人类本质中最殷切的需求是渴望得到他人的肯定。</p></blockquote><blockquote><p>📌 地赞赏他人，让他人感到自己很重要。</p></blockquote><blockquote><p>📌 永远避免正面冲突，那才是正确的。</p></blockquote><blockquote><p>📌 如果你辩论和反驳，或许你可以得到胜利，但那胜利是短暂而空虚的，因为你永远得不到对方对你的好感。</p></blockquote><blockquote><p>📌 一个科学家，永远不敢求证些什么，我只试着去寻求事实。</p></blockquote><blockquote><p>📌 换句话说，别跟你的顾客、朋友，或是敌人争辩，别指责他错了，别激怒他，不妨用点外交手腕。</p></blockquote><blockquote><p>📌 愚蠢的人都会尽力为自己的错误进行辩护，而且大多数的人都会这样做。</p></blockquote><blockquote><p>📌 人的思想是不容易改变的。你不能强迫别人同意你，但你完全有能力去引导他们，前提是只要你温和友善地去对待他们。</p></blockquote><blockquote><p>📌 一滴蜂蜜要比一加仑的胆汁更招引苍蝇。</p></blockquote><blockquote><p>📌 下次当你想告诉别人他犯了错的时候，请记住苏格拉底这一有效的法则，问一些温和的问题，一些可以引发别人作出“是”反应的问题。</p></blockquote><blockquote><p>📌 实际上，即使是我们的朋友，也喜欢谈论他们自己的成就而不愿意只听我们吹嘘自己的成就。</p></blockquote><blockquote><p>📌 当你我都要逝去，百年之后也许会被人完全遗忘。生命短暂，不要总是谈论那些小小的成就，否则会使人厌烦。反之，我们应该鼓励他人说话。</p></blockquote><blockquote><p>📌 没有人喜欢被迫去买一样不需要的东西，或是被人派遣去做一件事。我们都喜欢随自己的心愿买东西，或是照着自己的意思去做事情。</p></blockquote><blockquote><p>📌 永远按照对方的观点去想，从他人的立场去看待事情，这或许会成为影响你终生事业的一个关键因素。</p></blockquote><blockquote><p>📌 我一点都不奇怪你有这种感觉。如果我是你，也会和你有一样的感觉。</p></blockquote><blockquote><p>📌 你不是生来就具有判断力的，一切都是由经验而来。</p></blockquote><blockquote><p>📌 想改变人而不引起他的反感，那就在批评以前，首先认识到自己的缺点。</p></blockquote><blockquote><p>📌 永远使人们乐意去做你所建议的事</p></blockquote><blockquote><p>📌 困难并不意味着不幸，或许它会是一种幸运的开始。</p></blockquote><blockquote><p>📌 人的幸福结局，并非是平淡、安稳的喜乐，而是轰轰烈烈地与不幸抗争。</p></blockquote><blockquote><p>📌 生命并不是一帆风顺的幸福之旅，而是时时摆动在幸与不幸、沉与浮、光明与黑暗之间的模式里。</p></blockquote><blockquote><p>📌 由于忙着计算自己所拥有的幸福，因此没有时间去诅咒自己的不幸。</p></blockquote><blockquote><p>📌 要喜欢、尊重、欣赏我们自己，这不但能培养出健康成熟的个性，也能增进与他人相处的能力。</p></blockquote><blockquote><p>📌 但我一想到自己的种种缺点，便失去了继续讲下去的勇气。” 她接着又十分详细地对我分析了她的弱点。 当她讲完后，我告诉她：“不要只想着自己的缺点。要知道，并不是缺点使你的演讲不成功，而是你还没有把自己的长处发挥出来。” 事实的确如此，并不是缺点使我们的演讲、艺术作品或个人性格显得失败。莎士比亚的戏剧里有许多历史和地理上的错误；狄更斯的小说也有不少过度矫情的地方。但是谁会在乎这些缺点呢？这些作品闪耀着不朽的光辉——由于它们的优点那么显著，以至于把缺点掩盖了。我们爱身边的朋友，是因为他们的种种优点，而根本不在乎其缺点。 说到这里，大家应该学会把注意力放在我们自身的好品质上，培养优点，克服弱点，如此才能不断进步并自我实现。</p></blockquote><blockquote><p>📌 人们只有在找到自我时，才会明白自己为什么会到这个世界上来、要做些什么事、以后将要到什么地方去等这类问题。</p></blockquote><blockquote><p>📌 现在先来分析这“令人乏味的人或事”所产生的条件或方式。 以下几种情况最会令人生厌，如果我们事先了解在自己身上是否发生过这些情形，并在今后加以避免，那不就会成为一个受欢迎的人吗？ 第一，说话不把握重点。 著名作家马克·吐温有篇作品，是模仿一个唠叨乏味的人，如何漫无边际地描述一件事，却从没有讲到要点的经过。故事是这样的：“啊，我跟你讲过我到西部参观哈比印第安村的事吗？我们是星期五早上出发……啊，不，应该是星期四。我告诉过你我们得星期四走，因为星期三我要去看牙医。我上面的牙有点松动，必须让牙医帮我修理一下。那个牙医真是啰唆，嘴不停地讲个没完没了。</p></blockquote><blockquote><p>📌 一次只流过一粒沙子，一次只做一件事”</p></blockquote><blockquote><p>📌 去做，最后公司不但没有损失这两万美元，反而赚了15000美元。 如果当时我只是一味地担心下去，恐怕根本做不到这一点。因为忧虑会毁掉我们集中精神的能力。当我们忧虑的时候，思绪会飘忽不定，从而丧失决策分析</p></blockquote><blockquote><p>📌 第一，问你自己：“可能发生的最坏情况是什么？”第二，如果你必须接受的话，就做好准备接受它。第三，镇定地想办法改善最坏的情况。</p></blockquote><blockquote><p>📌 我发现如果一个人能够把所有忧虑的时间用在以一种很超然、很客观的态度去寻找事实的话，那他的忧虑便会在知识的光芒下，消失得无影无踪。”</p></blockquote><blockquote><p>📌 “一，我担心什么？”“二，我能怎么办？”</p></blockquote><blockquote><p>📌 第二，写下我们可以怎么办以及可能产生的结果。 第三，决定该怎么办。 第四，马上按照决定去做。 威廉·詹姆斯说：“一旦作出决定，当天就要付诸实践，而且不要理会责任问题，也不要关心后果。”也就是说，你一旦</p></blockquote><blockquote><p>📌 那么，我们何不马上运用格兰·李克菲的方法来解决下面的问题呢？ 第一个问题：我担忧什么？ 第二个问题：我能怎么办？ 第三个问题：我决定怎么做？ 第四个问题：我什么时候开始做？ 如果一个人可以把他所有忧虑</p></blockquote><blockquote><p>📌 人们之所以忧虑，就是有空闲时间来想自己到底快乐不快乐。”</p></blockquote><blockquote><p>📌 聪明人永远不会坐在那里，为他们的错误而悲伤；相反，他们会很高兴地寻求办法来弥补创伤。”</p></blockquote><blockquote><p>📌 法，剩下的就要看你自己的了。 小结： 只有分析清楚问题，才能有效地解决问题，走上成功之路。为此，我们要问自己以下问题： 第一，问题是什么？ 第二，问题的起因是什么？ 第三，解决问题的方法有哪些？</p></blockquote><blockquote><p>📌 只有分析清楚问题，才能有效地解决问题，走上成功之路。为此，我们要问自己以下问题：第一，问题是什么？第二，问题的起因是什么？第三，解决问题的方法有哪些？第四，你建议用哪一种解决方法？</p></blockquote><blockquote><p>📌 是现金吗？ 不。 他留给她们有价证券，使这些妇女每个月都可得到固定的收入。 在购买保险之前，我建议你读两本有益的小册子：《如何购买保险》、《买你自己的保险》，这些书现在已经绝版，但你可以在公立图书馆借</p></blockquote><blockquote><p>📌 一个读高中的儿子或女儿，而你希望他们学习如何理财，那我在此郑重地向你推荐一本书。书名为《处理你的金钱》，它对十几岁的学生如何用钱，有很精辟而且实际的见解。从理发到可乐，无所不包。同时，这本书也提到了如</p></blockquote><blockquote><p>📌 处理你的金钱</p></blockquote><blockquote><p>📌 《何计出胜算》的书，作者是奥斯华·贾柯比。他是桥牌及扑克牌的权威，也是最高级的计算专家和统计专家，以及保险公司的统计顾问。这本书一共215页，其中告诉你在玩赛马、轮盘、骰子、吃角子机、扑克、桥牌、梭哈</p></blockquote><blockquote><p>📌 如果我们得不到自己所希望的东西，那最好不要让忧虑和悔恨来侵扰我们的生活。让我们原谅自己，学得豁达一些。</p></blockquote><blockquote><p>📌 金钱并不是万能的，但如果知道如何聪明地处理我们的金钱，就可以带给你的丈夫和家庭更多的安宁、幸福与利益。所以，我们不能幻想着自己的丈夫能够带回来一大袋的薪水，这只会浪费我们的时间，损毁我们的青春。我们的</p></blockquote><blockquote><p>📌 人，不管每月挣多少薪水，都不会弄到仅够糊口的地步。 你认为不考虑眼前的问题，将来可以从头做起吗？ 你认为今年弃荒田于不顾，明年就可以重新耕种吗？ 你认为明天永远会有比今天更多的收入吗？ 时间是毫不留情</p></blockquote><blockquote><p>📌 请你牢记：你将来的欢乐和困苦，都将取决于你撒下的种子。等到将来，当你走进仓库，看见的是满仓的粮食还是无用的杂草，是光荣的成功还是凄惨的失败，这都要看你现在是怎样做的。</p></blockquote><blockquote><p>📌 如果你是一位打字员，那你不可能每天在办公室里睡午觉；如果你是一位会计，也不可能躺在长沙发上跟你的老板讨论账目问题。但是，如果你住在一个小城市里，那就可以在每天中午回家吃午餐的时候，在饭后睡上10分钟午</p></blockquote><blockquote><p>📌 使人立刻觉得舒畅许多。 所以，如果我们再碰到什么情感上的困难，为什么不去找个人谈谈呢？当然，并不是要你随便找一个人，就把心里所有的苦水和牢骚说给人家听。我们要找一个自己可以信任的人，如一位亲戚、一位医</p></blockquote><h2 id="书评" tabindex="-1">书评 <a class="header-anchor" href="#书评" aria-label="Permalink to &quot;书评&quot;">​</a></h2><blockquote><p>💭 写的非常好</p><p>📌 “没有任何人能侮辱我或困扰我，”他回答说，”我不允许他们这么做。” 也没有任何人能够侮辱我们或困扰我们，除非我们自己允许。 棍棒石头可以打断我的骨头，但语言却休想动我分毫。</p></blockquote><blockquote><p>💭 发觉自身潜能和优势，并将这些优势最大化的表现出来</p><p>📌 一个人总有一天会明白，嫉妒是没有用的，模仿他人无异于自杀。因为不论好坏，人只有自己才能够帮助自己，只有耕种自己的田地，才能收获自家的玉米</p></blockquote><blockquote><p>💭 总是想着接踵而来的事情可以很快解决，但随着一件件事情都需要处理的时候会感觉到无能为力和焦虑</p><p>📌 不会因为工作过于疲劳而死亡，却会死于浪费和忧虑。</p></blockquote><blockquote><p>💭 根据事情的轻重缓急去做</p><p>📌 让我们晕头转向的，并不是繁重的工作，而是我们没有搞清楚自己有多少工作，应该先做什么工作。</p></blockquote><blockquote><p>💭 坐的久了内心就会开始躁动起来</p><p>📌 是情绪在体内制造紧张的因素，让我们感到疲倦。</p></blockquote><blockquote><p>💭 让身体放松不会影响大脑的运转，会让你减少身体感受到的疲劳</p><p>📌 放松！放松！再放松！要让自己在工作的时候学会放松！</p></blockquote><blockquote><p>💭 兴趣才是最好的老师</p><p>📌 “能做自己喜欢做的事情的人，是最幸运的人。”</p></blockquote><blockquote><p>💭 行为也能间接控制感觉</p><p>📌 先在你的脸上堆起一个大大的真正的微笑，放松肩膀，好好地深吸一口气，再唱首歌。如果不会唱，就吹口哨；不会吹口哨的，就哼唱。很快地，你就会明白威廉·詹姆斯的意思——如果你的行为散发的是快乐，就不可能在心理上保持忧郁。</p></blockquote><blockquote><p>💭 心存善念</p><p>📌 憎恨不会伤害对方一根汗毛，却把自己的日子弄成了地狱。</p></blockquote><blockquote><p>💭 写的非常好</p><p>📌 “没有任何人能侮辱我或困扰我，”他回答说，”我不允许他们这么做。”</p></blockquote><blockquote><p>💭 人的预期会随着生活和精神的质量提高，相对而言也会随之减少</p><p>📌 那次经历给我的最大启迪是，只要有足够的水与食物，你就不该再有任何抱怨。</p></blockquote><blockquote><p>💭 饮食有度，保持平和以及愉悦的心情</p><p>📌 世上最好的医生，就是饮食有度、保持平和以及愉悦的心情。</p></blockquote><blockquote><p>💭 停止内耗</p><p>📌 撑起一把伞，让批评之雨顺着伞滑落。</p></blockquote><blockquote><p>💭 没有条件就创造条件</p><p>📌 人们时常抱怨自己的环境不顺利，因此使他们没有什么成就。我是不相信这种说法的。假如你得不到所要的环境，可以制造出一个来啊！</p></blockquote><blockquote><p>💭 每天进步一小步</p><p>📌 只要一步就好。</p></blockquote>',121)])])}const n=e(c,[["render",u]]);export{d as __pageData,n as default};
